/// 按经纬度找这个站点的第二批点值。
///
/// 判据与 [`crate::urban_soil::lookup`] 完全一致 —— 两张表按同一个键对齐，
/// 一张命中而另一张没命中会是个说不清的状态。
pub fn lookup(lon: f64, lat: f64) -> Option<&'static UrbanExtra> {
    SITES
        .iter()
        .find(|s| (s.lon - lon).abs() < 1e-3 && (s.lat - lat).abs() < 1e-3)
}

